function parseNPPSFile(text) {
  const tokens = tokenize(text);
  const parser = new Parser(tokens);
  const entries = parser.parse();
  return { entries, zones: [...parser.zones], conditions: [...parser.conditions] };
}
function buildNamespace(files) {
  const entries = [];
  const zones = new Map;
  const conditions = new Map;
  const errors = [];
  const collidedZones = new Set;
  const collidedConditions = new Set;
  for (const f of files) {
    entries.push(...f.entries);
    for (const z of f.zones) {
      if (collidedZones.has(z.name))
        continue;
      if (zones.has(z.name)) {
        errors.push(`Duplicate zone name '${z.name}' — defined in more than one file; zone names must be ` + `unique across the protocol directory. The name is left undefined.`);
        zones.delete(z.name);
        collidedZones.add(z.name);
        continue;
      }
      zones.set(z.name, z);
    }
    for (const c of f.conditions) {
      if (collidedConditions.has(c.name))
        continue;
      if (conditions.has(c.name)) {
        errors.push(`Duplicate condition name '${c.name}' — defined in more than one file; condition names ` + `must be unique across the protocol directory. The name is left undefined.`);
        conditions.delete(c.name);
        collidedConditions.add(c.name);
        continue;
      }
      conditions.set(c.name, c);
    }
  }
  return { namespace: { entries, zones, conditions }, errors };
}
function validateNamespaceReferences(ns) {
  const errors = [];
  for (const entry of ns.entries) {
    const def = entry.kind === "single" ? entry.protocol : entry.composite;
    for (const cond of def.conditions ?? []) {
      if (!ns.conditions.has(cond)) {
        errors.push(`Protocol '${def.name}' references undefined condition '${cond}'`);
      }
    }
    if (entry.kind === "single") {
      for (const m of entry.protocol.modalities) {
        if (m.modalityParams.type === "pbm_transcranial") {
          for (const zref of m.modalityParams.params.zoneRefs ?? []) {
            if (!ns.zones.has(zref)) {
              errors.push(`Protocol '${def.name}' references undefined zone '${zref}'`);
            }
          }
        }
      }
    }
  }
  return errors;
}

// simulator/src/npps-runtime.ts
var DEFAULT_BASE_URL = "../protocols/predefined/";
var T2_ONLY_MODALITY_TYPES = new Set([
  "qeeg_21ch",
  "tms",
  "pbm_deep_1170nm",
  "clinical_tacs",
  "hd_tdcs",
  "cervical_vns"
]);
var PBM_PEAK_MW_CM2 = 400;
var PROTOCOLS = {};
var PROTOCOL_IDS = [];
var ZONES = [];
var LOAD_REPORT = { compositesSkipped: 0, duplicateDefinitions: [], unresolvedReferences: [] };
